const CACHE='muroblocks-static-v2';
const base=self.registration.scope;
const files=['','index.html','manifest.webmanifest','src/main.js','src/styles.css','src/design/themes.js','src/game/shapes.js','src/game/logic.js','src/storage/db.js','pwa/icon-192.png','pwa/icon-512.png','pwa/apple-touch-icon.png','pwa/icon-maskable-512.png','icons/cat-logo.svg',...['foot','heart','leave','pumpkin','snow'].map(x=>`icons/pattern-${x}.svg`)];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(files.map(f=>new URL(f,base).href))).then(()=>self.skipWaiting()));});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('muroblocks-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{const req=event.request;if(req.method!=='GET'||new URL(req.url).origin!==location.origin)return;if(req.mode==='navigate'){event.respondWith(fetch(req).then(response=>{const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(req,copy));return response;}).catch(async()=>await caches.match(req)||await caches.match(new URL('index.html',base).href)));return;}event.respondWith(caches.match(req).then(cached=>cached||fetch(req).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(req,copy));}return response;})));});
